steps.starter:
{{pins}}
#include <DHT.h>

DHT dht(DHT_PIN, DHT11);  // use DHT22 if you have the white one

void setup() {
  Serial.begin(115200);
  dht.begin();
}

void loop() {
  float t = dht.readTemperature();
  float h = dht.readHumidity();
  if (isnan(t) || isnan(h)) {
    Serial.println("No reading. Check the wires.");
  } else {
    Serial.print("Temperature: ");
    Serial.print(t);
    Serial.print(" C  Humidity: ");
    Serial.print(h);
    Serial.println(" %");
  }
  delay(2000);
}

