steps.starter:
{{pins}}
#include <WiFi.h>
#include <WebServer.h>
#include <DHT.h>

DHT dht(DHT_PIN, DHT11);  // use DHT22 if you have the white one

WebServer server(80);

void homePage() {
  float t = dht.readTemperature();
  float h = dht.readHumidity();
  String page = "<!DOCTYPE html><html><head>";
  page += "<meta name=\"viewport\" content=\"width=device-width\">";
  page += "</head><body style=\"font-family: sans-serif; text-align: center\">";
  page += "<h1>Weather</h1>";
  page += "<p style=\"font-size: 2em\">" + String(___, 1) + " &deg;C</p>";
  page += "<p style=\"font-size: 2em\">" + String(___, 0) + " % humidity</p>";
  page += "</body></html>";
  server.send(200, "text/html", page);
}

void setup() {
  Serial.begin(115200);
  dht.begin();
  WiFi.softAP("ArduinoPath-Weather", "circuit123");
  server.on("/", homePage);
  server.begin();
  Serial.print("Open http://");
  Serial.println(WiFi.softAPIP());
}

void loop() {
  server.handleClient();
}

